param([ValidateSet('build','test','arguments')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-positive-karatsuba-20260913';$seed='D:\projects\AIMA-public-karatsuba-core-20260913'
$sha='91b069bd9532094735391c9f2bd97080e0a402bb';$bundle='D:\projects\positive-karatsuba-91b069b.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '756d9e65d9599d4ba4d2d7cdb6bb2b28da8630e9e5ff1d8f29250034593f0817'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\positive-karatsuba';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\sm121_positive_karatsuba_selftest.cpp';$exe=Join-Path $build 'positive-karatsuba.exe'
$sourceInputs=@();foreach($name in @(& git -C $repo ls-files 'native/providers/moe_accumulator/*.h' 'native/providers/ck_fmha/*.h' 'tests/native/sm121_positive_karatsuba_selftest.cpp' 'scripts/baiying_guarded_inference.ps1' 'tests/powershell/test_guarded_inference_arguments.ps1')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; two original IU8 partials plus one nonnegative FP16 partial0..510, with exact integer centering; original four-IU8 and CPU int64 comparisons; no snapping or product dispatch';model_loaded=$false;inference_acceptance=$false}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
}elseif($Action -eq 'arguments'){
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $repo 'tests\powershell\test_guarded_inference_arguments.ps1'));$timeout=30
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$timeout=90
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\positive-karatsuba-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12|ForEach-Object {$_.Substring(0,[Math]::Min(700,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native core action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}elseif($Action -eq 'arguments'){
 $report=[IO.File]::ReadAllText((Join-Path $out 'product.stdout.jsonl'))|ConvertFrom-Json
 if(-not $report.pass -or $report.cases -ne 4 -or -not $report.actual_guard_block -or $report.process_started){throw 'Argument transport test failed'}
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 4){throw 'Missing core cases'}
 foreach($report in $reports){if(-not $report.redzones_pass -or -not $report.immutable_inputs){throw 'Core guard failure'};if($report.kind -eq 'positive_karatsuba_integer_core'){if($report.integer_partial_mismatches -ne 0 -or $report.candidate_raw_partial_mismatches -ne 0 -or $report.reconstruction_mismatches -ne 0){throw 'Core bits changed'}}elseif($report.kind -eq 'positive_karatsuba_core_sequence'){if($report.checksum_mismatches -ne 0){throw 'Sequence bits changed'}}else{throw 'Unexpected report'}}
}

